<?php
if (!defined("SUAVE_RAIZ")) { http_response_code(404); exit; } use Suave\Interfaz as V;use Suave\Numeros as N;
$case=$db->one('SELECT c.*,co.mes,co.reporte_id,r.numero AS reporte_numero,r.modalidad FROM casos c JOIN comparaciones co ON co.id=c.comparacion_id JOIN reportes r ON r.id=co.reporte_id WHERE c.id=?',[(int)($_GET['id']??$_POST['id']??0)]);if(!$case)throw new Suave\ErrorUsuario('El caso no existe.');
$casePeriod=(new Suave\Periodos($db))->get($case['mes']);$readOnly=$case['estado']!=='Pendiente'||$case['fusionado_en']||$casePeriod['estado']==='Revisado'||(int)$casePeriod['comparacion_id']!==(int)$case['comparacion_id'];
$versions=Suave\Datos::decode($case['versiones_json']);$rowIds=Suave\Datos::decode($case['filas_json']);$detail=Suave\Datos::decode($case['detalle_json']);$draft=$detail['avance']??$detail['resolucion']??[];
$notes=$db->all(Suave\Entregas::CURRENT." WHERE v.mes=? AND v.sucursal_codigo=? AND v.estado='Registrada' ORDER BY v.fecha,e.id",[$case['mes'],$case['sucursal_codigo']]);$rows=$db->all('SELECT * FROM reporte_filas WHERE reporte_id=? AND sucursal_codigo=? ORDER BY hoja,fila',[$case['reporte_id'],$case['sucursal_codigo']]);
$noteOptions=[''=>'Sin nota: documentar ausencia'];foreach($notes as $n)$noteOptions[$n['id']]=$n['referencia'].' · '.V::date($n['fecha']).' · '.($n['folio']?:'Sin folio').' · '.N::currency((int)$n['total_centavos']);
$rowOptions=[''=>'Sin fila: documentar ausencia'];foreach($rows as $r)$rowOptions[$r['id']]=$r['hoja'].' · fila '.$r['fila'].' · '.($r['fecha']?V::date($r['fecha']).' · ':'').($r['folio']?:'Sin folio').' · '.N::currency((int)$r['importe_centavos']);
?>
<div class="page-heading"><div><h1>Caso C-<?=$case['id']?></h1><p><?=V::h($case['sucursal_codigo'].' · '.V::monthLabel($case['mes']))?> · Reporte v<?=$case['reporte_numero']?></p></div><?=V::badge($case['estado'])?></div>
<?php if($case['fusionado_en']):?><div class="notice">Este asunto se integró en <?=$w->link('C-'.$case['fusionado_en'],'caso',['id'=>$case['fusionado_en']],'text-link')?>. Sus revisiones anteriores permanecen aquí.</div><?php endif?>
<?php if((int)$casePeriod['comparacion_id']!==(int)$case['comparacion_id']):?><div class="notice">Este caso pertenece a una comparación histórica y se consulta sin modificarlo.</div><?php endif?>
<div class="detail-grid"><section class="soft-panel"><h2>SUAVE: <?=N::currency((int)$case['suave_centavos'])?></h2><p><?=count($versions)?> versión(es) de nota incluidas.</p><?php foreach($versions as $vid):$n=$db->one('SELECT v.*,e.referencia FROM entrega_versiones v JOIN entregas e ON e.id=v.entrega_id WHERE v.id=?',[$vid]);if($n):?><p><?=$w->link($n['referencia'].' v'.$n['numero'],'ver_entrega',['id'=>$n['entrega_id'],'version'=>$n['numero'],'volver'=>'conciliacion'],'text-link')?> · Folio <?=V::h($n['folio']?:'Sin folio')?></p><?php endif;endforeach?></section><section class="soft-panel"><h2>Excel: <?=$case['excel_centavos']===null?'Sin contraparte':N::currency((int)$case['excel_centavos'])?></h2><p>Se conservan los valores recibidos del cliente.</p><?php foreach($rowIds as $rid):$r=$db->one('SELECT * FROM reporte_filas WHERE id=?',[$rid]);if($r):?><p><?=V::h($r['hoja'].' · fila '.$r['fila'].' · '.($r['folio']?:'Sin folio'))?></p><?php include __DIR__.'/_reporte_origen.php';endif;endforeach?><p class="hint">La correspondencia se revisa por documento. Las columnas originales son un apoyo de consulta; no se infieren ventas finales, impuestos ni reglas de devoluciones.</p></section></div>
<?php if(!$readOnly):?><form method="post" data-dirty><?=V::protect('caso_guardar')?><?=V::hidden('id',$case['id'])?><?=V::hidden('revision',$case['revision'])?><?=V::hidden('mes',$case['mes'])?>
<?php if($case['modalidad']==='detalle'):?><h2>Comprueba la correspondencia con sus respaldos</h2><div class="form-grid"><?=V::select('Nota SUAVE','version_id',$noteOptions,V::value('version_id',$draft['version_id']??($versions[0]??'')))?><?=V::select('Fila del cliente','fila_id',$rowOptions,V::value('fila_id',$draft['fila_id']??($rowIds[0]??'')))?></div><p class="hint">Si falta una contraparte, conserva la ausencia y documéntala. Una fuente ya resuelta no puede utilizarse otra vez.</p><?php endif?>
<div class="form-grid three"><?=V::select('Resultado de revisión *','resultado',[''=>'Selecciona un resultado','vinculo_confirmado'=>'Correspondencia confirmada','diferencia_documentada'=>'Diferencia documentada','ausencia_documentada'=>'Ausencia documentada','total_revisado'=>'Total mensual revisado'],V::value('resultado',$draft['resultado']??''),['required'=>true])?><?=V::input('Importe validado del caso *','validado',V::value('validado',isset($draft['validado_centavos'])?N::input((int)$draft['validado_centavos']):''),'number',['step'=>'0.01','required'=>true])?><?=V::input('Respaldo de la revisión *','evidencia',V::value('evidencia',$draft['evidencia']??''),'text',['maxlength'=>2000,'required'=>true,'placeholder'=>'Documento o ubicación comprobada'])?></div>
<?=V::textarea('Explicación y motivo *','explicacion',(string)V::value('explicacion',$draft['explicacion']??''),true)?>
<div class="action-row spread form-actions"><?=$w->link('Volver','conciliacion',['mes'=>$case['mes']])?><div class="action-row"><button class="button" type="submit" name="intencion" value="avance" formnovalidate>Guardar avance</button><button class="button primary" type="submit" name="intencion" value="resolver">Resolver caso</button></div></div></form>
<?php else:?>
<div class="soft-panel"><h2>Conclusión conservada</h2><p><strong>Importe validado: <?=$case['validado_centavos']===null?'Incompleto':N::currency((int)$case['validado_centavos'])?></strong></p><p><?=V::h($draft['evidencia']??'')?></p><p><?=nl2br(V::h($draft['explicacion']??($detail['nota']??'')))?></p></div><div class="action-row"><?=$w->link('Volver a conciliación','conciliacion',['mes'=>$case['mes']])?></div><?php endif?>
<?php $revisions=$db->all('SELECT * FROM caso_revisiones WHERE caso_id=? ORDER BY id',[$case['id']]);if($revisions):?><section class="section-block"><h2>Historial de revisión</h2><div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Acción</th><th>Explicación conservada</th></tr></thead><tbody><?php foreach($revisions as $revision):$data=Suave\Datos::decode($revision['datos_json']);$decision=$data['decision']??$data['detalle']['resolucion']??$data;?><tr><td><?=V::h($revision['creado_en'])?></td><td><?=V::h($revision['accion'])?></td><td><?=V::h($decision['explicacion']??(isset($data['caso_anterior'])?'Se conserva la decisión del caso C-'.$data['caso_anterior'].'.':'Fuentes integradas sin duplicar importes.'))?></td></tr><?php endforeach?></tbody></table></div></section><?php endif?>
